{
 "id": "01a0fc81-9829-71e1-94a9-4002b82b4a1a",
 "content": "scripts/export.py produces the monthly invoice report that Finance imports into their accounting tool at the start of each month. It runs from the ops cron on the 2nd at 06:00 UTC and writes one file per environment to EXPORT_BUCKET under `exports/<YYYY-MM>/invoices.csv`. Finance reconciles the totals against the ledger, so every finalized invoice of the month must appear exactly once, including zero-amount ones; drafts are excluded. Columns, in order: invoice id, customer id, subtotal, tax, total, finalized date. Amounts are integer cents with no currency symbol. Format (since Finance switched accounting tools in late September 2026): plain comma-separated, dates in ISO format `YYYY-MM-DD` (strftime `%Y-%m-%d`), UTF-8 without a BOM. The previous tool's semicolon delimiter and DD.MM.YYYY dates no longer apply.",
 "status": "active"
}
